#!/usr/bin/env python3
"""Worker latar: add/commit/push log Hermes ke GitHub.

Dijalankan sebagai daemon oleh ``autopush_worker.sh``. Menunggu trigger,
kemudian memproses SATU operasi git pada satu waktu. Bila push gagal karena
jaringan, request dipertahankan dan dicoba ulang dengan backoff; log lokal
tidak pernah dihapus atau di-rollback.
"""
from __future__ import annotations

import fcntl
import os
import sys
import time
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT))

import autopush_queue as q  # noqa: E402
from autopush_push import push_once  # noqa: E402

LOG = ROOT / "logs" / "tool-results" / "sync-errors.log"
LOCK = q.LOCKS / "git.lock" / "worker.lock"

IDLE = 5.0
MAX_WAIT = 120.0


def note(msg: str) -> None:
    try:
        LOG.parent.mkdir(parents=True, exist_ok=True)
        with LOG.open("a", encoding="utf-8") as fh:
            fh.write(f"{datetime.now().astimezone().isoformat(timespec='seconds')} {msg}\n")
    except OSError:
        pass


def pending() -> int:
    try:
        return len(list(q.QUEUE.glob("*.json")))
    except OSError:
        return 0


def drain() -> int:
    """Hapus request yang sudah tersentuh dari antrean.

    Worker memegang .locks/git.lock/worker.lock sepanjang operasi, jadi
    penghapusan di sini aman. Request baru (dari hook yang berjalan bersamaan)
    tertulis ke file baru dan TIDAK ikut terhapus.
    """
    n = 0
    for path in q.QUEUE.glob("*.json"):
        try:
            path.unlink()
            n += 1
        except OSError:
            pass
    return n


def main() -> int:
    try:
        LOCK.parent.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass

    fd = os.open(str(LOCK), os.O_CREAT | os.O_RDWR, 0o644)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)  # satu worker saja; menunggu bila ada worker lain
    except OSError:
        pass

    try:
        while True:
            if pending() == 0:
                try:
                    time.sleep(IDLE)
                except KeyboardInterrupt:
                    return 0
                continue

            delay = IDLE
            ok, detail = push_once()
            if ok:
                removed = drain()
                remaining = pending()
                note(f"push ok ({detail}); request dihapus={removed}; sisa antrean={remaining}")
                if remaining == 0:
                    time.sleep(IDLE)
                continue

            # Gagal: simpan request, coba lagi maksimal MAX_WAIT detik.
            note(f"push gagal: {detail}; retry dalam {delay:.0f}s")
            waited = 0.0
            while waited < MAX_WAIT:
                time.sleep(delay)
                waited += delay
                ok, detail = push_once()
                if ok:
                    break
                delay = min(delay * 2, 30.0)
            if ok:
                drain()
                note(f"push berhasil setelah retry ({detail}); sisa antrean={pending()}")
            else:
                note(f"push masih gagal setelah retry: {detail}; antrean dipertahankan")
    except KeyboardInterrupt:
        return 0
    finally:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(fd)


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        sys.exit(0)
